'use strict';
const assert=require('node:assert/strict');const{createHash}=require('node:crypto');
const OBJECTIVE='ss_mail_agent_cross_persona_read';
async function admitV11DisposableCandidate({migration,catalog,administratorContext,curriculum}={}){const checked=curriculum?.OBJECTIVES?.find(row=>row.id===OBJECTIVE);assert(['pending','native-browser-judge'].includes(checked?.qualification));assert.equal(checked.defaultEnabled,false);const productionQualified=checked.qualification==='native-browser-judge';assert.equal(curriculum.isQualifiedObjective(OBJECTIVE),productionQualified);const source=JSON.stringify({version:1,id:checked.id,label:checked.text,defaultEnabled:checked.defaultEnabled,qualification:checked.qualification});const sha=createHash('sha256').update(source).digest('hex');let row=(await catalog.list(administratorContext)).objectives.find(value=>value.objectiveId===OBJECTIVE);assert.equal(row?.qualification,checked.qualification);assert.equal(row.enabled,false);if(!productionQualified){await assert.rejects(catalog.set(administratorContext,{objectiveId:OBJECTIVE,enabled:true,expectedRevision:row.revision}),{code:'SHOP_OBJECTIVE_UNQUALIFIED'});const changed=await migration.query("UPDATE secureshop_auth.assessment_objectives SET qualification='native-browser-judge' WHERE objective_id=$1 AND qualification='pending' AND is_enabled=false AND catalog_active=true AND configuration_source='checked_in_default' AND source_sha256=$2 AND source_document=$3::jsonb RETURNING objective_id,qualification,is_enabled",[OBJECTIVE,sha,source]);assert.equal(changed.rowCount,1);assert.deepEqual(changed.rows,[{objective_id:OBJECTIVE,qualification:'native-browser-judge',is_enabled:false}]);row=(await catalog.list(administratorContext)).objectives.find(value=>value.objectiveId===OBJECTIVE);assert.equal(row.qualification,'native-browser-judge');assert.equal(row.enabled,false);}const enabled=await catalog.set(administratorContext,{objectiveId:OBJECTIVE,enabled:true,expectedRevision:row.revision});assert.equal(enabled.enabled,true);assert.equal(enabled.qualification,'native-browser-judge');return Object.freeze({objectiveId:OBJECTIVE,fixtureLocalCandidateAdmission:!productionQualified,productionQualification:checked.qualification,productionDefaultEnabled:false});}
module.exports={V11_OBJECTIVE:OBJECTIVE,admitV11DisposableCandidate};
